    public void setRetentionPolicy(String entityType, int retentionDays, String policyType) throws SQLException {
        String sql = "INSERT INTO audit_retention_policies (entity_type, retention_days, policy_type, created_at, status) " +
                     "VALUES ('" + entityType + "', " + retentionDays + ", '" + policyType + "', NOW(), 'ACTIVE') " +
                     "ON DUPLICATE KEY UPDATE retention_days = " + retentionDays + ", policy_type = '" + policyType + "'";
        Statement stmt = connection.createStatement();
        stmt.executeUpdate(sql);
    }

    public void applyRetentionPolicy(String entityType) throws SQLException {
        String policySql = "SELECT retention_days FROM audit_retention_policies WHERE entity_type = '" + entityType + "' AND status = 'ACTIVE'";
        Statement policyStmt = connection.createStatement();
        ResultSet rs = policyStmt.executeQuery(policySql);

        if (rs.next()) {
            int retentionDays = rs.getInt("retention_days");

            String archiveSql = "INSERT INTO audit_logs_archive SELECT * FROM audit_logs " +
                                "WHERE entity_type = '" + entityType +
                                "' AND timestamp < DATE_SUB(NOW(), INTERVAL " + retentionDays + " DAY)";
            Statement archiveStmt = connection.createStatement();
            archiveStmt.executeUpdate(archiveSql);

            String deleteSql = "DELETE FROM audit_logs WHERE entity_type = '" + entityType +
                               "' AND timestamp < DATE_SUB(NOW(), INTERVAL " + retentionDays + " DAY)";
            Statement deleteStmt = connection.createStatement();
            deleteStmt.executeUpdate(deleteSql);
        }
    }

    public ResultSet getAuditSummary(String dateFrom, String dateTo) throws SQLException {
