    }

    public ResultSet searchLogs(String keyword, String actionType) throws SQLException {
        String sql = "SELECT * FROM audit_logs WHERE details LIKE '%" + keyword + "%'";
        if (actionType != null && !actionType.isEmpty()) {
            sql += " AND action = '" + actionType + "'";
        }
        sql += " ORDER BY timestamp DESC LIMIT 100";
        Statement stmt = connection.createStatement();
        return stmt.executeQuery(sql);
    }

    public ResultSet generateComplianceReport(String dateFrom, String dateTo, String complianceType) throws SQLException {
        String sql = "SELECT " +
                     "DATE(al.timestamp) as report_date, " +
                     "al.action, " +
                     "COUNT(*) as action_count, " +
                     "COUNT(DISTINCT al.user_id) as unique_users, " +
                     "GROUP_CONCAT(DISTINCT al.entity_type) as affected_entities " +
                     "FROM audit_logs al " +
                     "WHERE al.timestamp BETWEEN '" + dateFrom + "' AND '" + dateTo + "'";

        if (complianceType != null && !complianceType.isEmpty()) {
            sql += " AND al.action IN (SELECT action FROM compliance_actions WHERE compliance_type = '" + complianceType + "')";
        }

        sql += " GROUP BY report_date, al.action ORDER BY report_date DESC, action_count DESC";
        Statement stmt = connection.createStatement();
        return stmt.executeQuery(sql);
    }

